export const effects={power:{label:'Dégâts +35 %',icon:'✦'},haste:{label:'Délai entre les tirs −25 %',icon:'ϟ'},spread:{label:'Deux projectiles supplémentaires',icon:'⋔'},speed:{label:'Déplacement +20 %',icon:'◇'},vitality:{label:'Un cœur en plus, vie restaurée',icon:'♥'},pierce:{label:'Les tirs traversent les ennemis',icon:'✧'}};
const string={type:'string',minLength:2,maxLength:65};
const choice=(values)=>({type:'string',enum:values});
const object=(properties)=>({type:'object',additionalProperties:false,properties,required:Object.keys(properties)});
export const schema=object({title:string,theme:choice(['moss','ember','violet']),layout:choice(['branch','cross','loop']),rule:choice(['swift','fierce','generous']),rooms:{type:'array',minItems:3,maxItems:3,items:object({name:string,pattern:choice(['pillars','corners','empty']),enemies:choice(['slime','eye','mixed']),count:{type:'integer',minimum:3,maximum:6}})},items:{type:'array',minItems:3,maxItems:3,items:object({name:string,effect:choice(Object.keys(effects))})},boss:object({name:string,pattern:choice(['ring','fan','spiral']),health:{type:'integer',minimum:110,maximum:180}})});
export function dayKey(date=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
export function hash(s){let h=2166136261;for(const ch of s){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
export function rng(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296}}
export function validateBlueprint(input){
 const check=(v,s,p)=>{if(s.type==='object'){if(!v||typeof v!=='object'||Array.isArray(v))throw Error(`${p} doit être un objet`);const out={};for(const k of s.required)out[k]=check(v[k],s.properties[k],`${p}.${k}`);return out}
 if(s.type==='array'){if(!Array.isArray(v)||v.length<s.minItems||v.length>s.maxItems)throw Error(`${p} : nombre d’éléments invalide`);return v.map((x,i)=>check(x,s.items,`${p}[${i}]`))}
 if(s.type==='string'){if(typeof v!=='string'||!v.trim()||v.length>65||/\p{Cc}/u.test(v))throw Error(`${p} : texte invalide`);if(s.enum&&!s.enum.includes(v))throw Error(`${p} : choix inconnu`);return v.trim()}
 if(s.type==='integer'){if(!Number.isInteger(v)||v<s.minimum||v>s.maximum)throw Error(`${p} : valeur hors limites`);return v}throw Error('Schéma inconnu')};
 return check(input,schema,'donjon');
}
export function validateDungeon(raw){if(!raw||raw.version!==1||!/^\d{4}-\d{2}-\d{2}$/.test(raw.date)||!Number.isInteger(raw.seed)||raw.seed<0||raw.seed>4294967295)throw Error('Format de donjon incompatible (version, date ou graine).');return {version:1,date:raw.date,seed:raw.seed,source:typeof raw.source==='string'?raw.source.slice(0,100):'import',blueprint:validateBlueprint(raw.blueprint)}}
export function demoDungeon(date=dayKey()){
 const random=rng(hash(date)),pick=(a)=>a[Math.floor(random()*a.length)];
 return {version:1,date,seed:hash(date),source:'demo',blueprint:{title:pick(['La crypte des échos','Le jardin des oubliés','Les braises du silence','La chapelle sans lune']),theme:pick(['moss','ember','violet']),layout:pick(['branch','cross','loop']),rule:pick(['swift','fierce','generous']),rooms:[{name:'Le vestibule',pattern:'pillars',enemies:'slime',count:3},{name:'La veillée',pattern:pick(['pillars','corners','empty']),enemies:'mixed',count:4},{name:'Le chœur brisé',pattern:'corners',enemies:'eye',count:4}],items:[{name:'Larme de lune',effect:'spread'},{name:'Dent du veilleur',effect:'power'},{name:'Cœur de mousse',effect:'vitality'}],boss:{name:pick(['Le Veilleur creux','L’Abbé des cendres','Le Dernier Écho']),pattern:pick(['ring','fan','spiral']),health:145}}};
}
export function buildRooms(dungeon){
 const b=dungeon.blueprint;
 const maps={branch:[[0,0],[1,0],[1,-1],[2,0],[2,1],[1,1],[3,0]],cross:[[0,0],[0,-1],[-1,-1],[1,-1],[1,-2],[0,-2],[2,-1]],loop:[[0,0],[1,0],[1,1],[2,0],[2,1],[3,1],[3,0]]};
 return maps[b.layout].map(([x,y],id)=>({id,x,y,type:['start','combat','treasure','combat','combat','treasure','boss'][id],name:id===0?'Le seuil':id===2||id===5?'Le reliquaire':id===6?b.boss.name:b.rooms[[1,3,4].indexOf(id)].name,plan:b.rooms[[1,3,4].indexOf(id)],visited:false,cleared:id===0||id===2||id===5,claimed:false,enemies:null}));
}
export function obstacles(pattern){return pattern==='pillars'?[{x:270,y:180,w:62,h:65},{x:628,y:180,w:62,h:65},{x:270,y:380,w:62,h:65},{x:628,y:380,w:62,h:65}]:pattern==='corners'?[{x:215,y:165,w:115,h:50},{x:630,y:165,w:115,h:50},{x:215,y:390,w:115,h:50},{x:630,y:390,w:115,h:50}]:[]}
export function proceduralDungeon(seed,date=dayKey()){const random=rng(seed),pick=a=>a[Math.floor(random()*a.length)],pool=Object.keys(effects),names={power:'Dent du veilleur',haste:'Sablier fêlé',spread:'Larme de lune',speed:'Pas de brume',vitality:'Cœur de mousse',pierce:'Aiguille spectrale'},result=demoDungeon(date),b=result.blueprint;result.seed=seed>>>0;result.source='procedural';b.title=pick(['La nef des oubliés','La crypte des échos','Les jardins du silence','Le cloître des braises','Le tombeau des songes']);b.theme=pick(['moss','ember','violet']);b.layout=pick(['branch','cross','loop']);b.rule=pick(['swift','fierce','generous']);b.rooms=b.rooms.map((r,i)=>({...r,pattern:pick(['empty','pillars','corners']),enemies:pick(['slime','eye','mixed']),count:3+Math.floor(random()*3)}));b.items=Array.from({length:3},()=>{const effect=pool.splice(Math.floor(random()*pool.length),1)[0];return {name:names[effect],effect}});b.boss.pattern=pick(['ring','fan','spiral']);b.boss.health=110+Math.floor(random()*51);return validateDungeon(result)}
export function hitsRect(x,y,r,o){return x+r>o.x&&x-r<o.x+o.w&&y+r>o.y&&y-r<o.y+o.h}
export function prompt(date=dayKey()){return `Tu conçois un donjon inédit pour le jeu Nocturne du ${date}. Univers gothique poétique, noms français courts, originaux. Invente un thème cohérent, trois salles de combat avec des compositions variées, trois reliques aux effets différents et un boss. Choisis uniquement les mécaniques du schéma, sans ajouter de code. Varie la topologie et les attaques. Le jeu possède sept salles au total et ajoute les salles de départ et de trésor. Réponds seulement avec un objet JSON conforme à ce schéma : ${JSON.stringify(schema)}`}
